/**
 * Compile the shared JSON in data/, maps/ and scenarios/ into
 * modules/php/Material.php.
 *
 * The JSON is the source of truth: the simulator reads it directly, and so did
 * the PHP until BGA's pre-release check refused `file_get_contents` ("Forbidden
 * PHP function detected"). BGA's documented home for static game data is PHP
 * arrays loaded with the code, so the PHP now gets the same files compiled into
 * one class, keyed by path — `Material::FILES['maps/grid12.json']` is exactly
 * what `json_decode` of that file returned. Nothing is read at runtime.
 *
 * The generated file is committed, like `src/ts/primers.generated.ts`, so a
 * review shows what actually ships. `tests/test_material.php` fails if it is
 * stale — a scenario edited without a rebuild would otherwise reach the
 * simulator and never the server.
 *
 * Run by `npm run build`; `tools/deploy.sh` runs that before every sync.
 */

import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const outFile = join(root, 'modules', 'php', 'Material.php');
const directories = ['data', 'maps', 'scenarios'];

/** A PHP string literal: single quotes, so only `\` and `'` need escaping. */
const phpString = text => `'${text.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;

/** A JSON value as a PHP literal, the way `json_decode($json, true)` would build it. */
function php(value, indent) {
    const pad = '    '.repeat(indent);
    const inner = '    '.repeat(indent + 1);
    if (value === null) {
        return 'null';
    }
    if (typeof value === 'boolean') {
        return value ? 'true' : 'false';
    }
    if (typeof value === 'number') {
        if (!Number.isInteger(value)) {
            // JSON.parse cannot tell 2 from 2.0, and json_decode can. Refuse
            // rather than guess, until a file actually needs a decimal.
            throw new Error(`non-integer ${value}: decide how it should reach PHP first`);
        }
        return String(value);
    }
    if (typeof value === 'string') {
        return phpString(value);
    }
    if (Array.isArray(value)) {
        if (value.length === 0) {
            return '[]';
        }
        return `[\n${value.map(v => inner + php(v, indent + 1)).join(',\n')},\n${pad}]`;
    }
    const entries = Object.entries(value);
    if (entries.length === 0) {
        return '[]';
    }
    return `[\n${entries.map(([k, v]) => `${inner}${phpString(k)} => ${php(v, indent + 1)}`).join(',\n')},\n${pad}]`;
}

const files = directories.flatMap(dir =>
    readdirSync(join(root, dir))
        .filter(name => name.endsWith('.json'))
        .sort()
        .map(name => `${dir}/${name}`));

const body = files
    .map(path => `        ${phpString(path)} => ${php(JSON.parse(readFileSync(join(root, path), 'utf8')), 2)},`)
    .join('\n');

const out = `<?php
/**
 * GENERATED by tools/build-material.mjs from ${directories.map(d => `${d}/`).join(', ')}.
 * Edit the JSON, then \`npm run build\` — never this file.
 */
declare(strict_types=1);

namespace Bga\\Games\\IronAndWhisper;

/**
 * The shared JSON, decoded, keyed by its path from the project root.
 *
 * BGA forbids reading files at runtime, so the JSON the simulator reads is
 * compiled into this class instead. See tools/build-material.mjs.
 */
final class Material
{
    public const FILES = [
${body}
    ];
}
`;

writeFileSync(outFile, out);
console.log(`wrote ${files.length} files to modules/php/Material.php`);
